// ============================================================================
// lanex_board.v - the LaneX desk lane on the DE10-Lite: everything around the
// RVBL-2 chip. Hand-written; the chip (lanex_chip.v) and the tables
// (lanex_data.v) are generated by scripts/stage4/gen_de10lite.py.
// Plan: docs/stage4/07_max10_prototype.md.
//
// The fabric is test equipment, the board's own version of the organisers'
// ./emu: it turns the sensors and switches into the chip's input pins and host
// frames, and the chip's records and lamp pins into the displays, lamps and
// buzzer. It decides nothing about a vehicle: LaneX runs only on the chip.
//
//   ultrasonic, SW, KEY1 -> the lane (presence, height class) -------+
//   boot, tag reader --> lx_framer (templates, live time, CRC) ------+--> lx_chipio --> chip
//   laptop UART -------> lx_hostlink (whole frames only) ------------+    one ordered
//   SW9 tour mode -----> lx_tour (the 12 AWS ./emu lines, checked) --+    channel
//   chip UART ---------> lx_records (8-byte records, CRC) --> display, lamps, buzzer
//                   \--> out to the laptop unchanged (it sees what the chip says)
//
// lx_chipio is the only way into the chip: pin changes and whole frames, one at
// a time, a pin change only between frames and followed by a settle time
// (PROTOCOL.md section 7). The order the chip sees is therefore the order the
// testbench logs, and the golden model replays exactly that order.
//
// One clock (the core clock, CLK_HZ); rst is synchronous, active high.
// ============================================================================
`default_nettype none

module lanex_board #(
    parameter integer CLK_HZ   = 31250000,
    parameter integer BAUD     = 115200,
    parameter integer TICK_DIV = CLK_HZ / 1000,   // core clocks per board millisecond
    parameter integer SETTLE   = 40000,           // core clocks after each pin change
    parameter integer BOOT_CYC = 10000,           // core clocks from a chip reset to its first frame
    parameter integer END_CYC  = 200000,          // tour: core clocks between a line's last input and its check
    parameter integer SONAR_PERIOD = CLK_HZ / 16, // core clocks between ultrasonic measurements (62.5 ms)
    parameter integer PRESENT_MM = 15,            // an object this tall under the sensor is a vehicle
    parameter integer TALL_MM  = 60               // a vehicle this tall is a lorry (class 3)
) (
    input  wire        clk,
    input  wire        rst,
    input  wire [9:0]  sw,
    input  wire        key1_n,       // KEY1, low when pressed (KEY0 is the reset, in lanex_de10lite)
    input  wire        sonar_echo,   // ultrasonic sensor (HC-SR04) Echo, through a divider to 3.3 V
    output wire        sonar_trig,   // ... and its Trig
    input  wire        host_rx,      // from the laptop's USB-UART (idles high)
    output wire        host_tx,      // to the laptop: the chip's own UART output
    output wire [47:0] hex_n,        // HEX5..HEX0, {dp,g,f,e,d,c,b,a} each, 0 = lit
    output wire [9:0]  ledr,
    output wire        lamp_green,
    output wire        lamp_white,
    output wire        lamp_red,
    output wire        lamp_closed,
    output wire        buzzer,       // a level: an active buzzer (it has its own oscillator)
    output wire        buzzer_tone   // a 2.4 kHz square wave while it sounds: a passive buzzer
);
    localparam integer CPB = (CLK_HZ + BAUD / 2) / BAUD;   // the chip UART's own formula
    localparam [2:0] PRESET_CLONE = 3'd5;
    localparam [3:0] TID_IDENTIFY = 4'd5, TID_SIGHTING = 4'd6;   // lanex_data.v lx_templates
    localparam [4:0] MSG_CLOSED = 5'd6, MSG_BLANK = 5'd7, MSG_ERR = 5'd16, MSG_ID = 5'd17,
                     MSG_NO_ID = 5'd18, MSG_TEST = 5'd19, MSG_PASS = 5'd20, MSG_FAIL = 5'd21;
    localparam [4:0] SP = 5'd31, DASH = 5'd27;
    localparam integer LAMP_MS = 1000, SCROLL_MS = 170, ID_MS = 2500;
    localparam [12:0] DEC_MS = 13'd4000, FARE_FROM = 13'd2500;  // a decision: word 1.5 s, then the fare 2.5 s

    // ------------------------------------------------------------------
    // Inputs: two flip-flops each, then debounced in board milliseconds
    // ------------------------------------------------------------------
    wire [9:0] sw_s;
    wire       k1_s, echo_s, host_rx_s;
    lx_sync #(.W(13), .INIT(13'h0001)) u_sync (
        .clk(clk), .d({sw, ~key1_n, sonar_echo, host_rx}),
        .q({sw_s, k1_s, echo_s, host_rx_s}));

    reg [15:0] tick_cnt;
    reg        tick;                 // one cycle per board millisecond
    reg [31:0] now_ms;               // the time stamp of the frames we send
    always @(posedge clk) begin
        if (rst) begin
            tick_cnt <= 16'd0; tick <= 1'b0; now_ms <= 32'd0;
        end else begin
            tick     <= (tick_cnt == TICK_DIV - 1);
            tick_cnt <= (tick_cnt == TICK_DIV - 1) ? 16'd0 : tick_cnt + 16'd1;
            if (tick) now_ms <= now_ms + 32'd1;
        end
    end

    wire       key1;
    wire [9:0] swd;
    lx_debounce #(.MS(10)) u_db_k1 (.clk(clk), .rst(rst), .tick(tick), .d(k1_s), .q(key1));
    genvar gi;
    generate
        for (gi = 0; gi < 10; gi = gi + 1) begin : g_sw
            lx_debounce #(.MS(10)) u_db (.clk(clk), .rst(rst), .tick(tick), .d(sw_s[gi]), .q(swd[gi]));
        end
    endgenerate
    wire       manual = swd[8];
    wire [2:0] preset = swd[5:3];

    // ------------------------------------------------------------------
    // The chip, its reset, and its pad tri-state resolved in the fabric
    // ------------------------------------------------------------------
    reg        chip_rst_req;
    reg  [7:0] chip_rst_cnt;
    wire       chip_rst = rst | chip_rst_req | (chip_rst_cnt != 8'd0);
    always @(posedge clk) begin
        if (rst | chip_rst_req) chip_rst_cnt <= 8'd200;
        else if (chip_rst_cnt != 8'd0) chip_rst_cnt <= chip_rst_cnt - 8'd1;
    end
    reg [15:0] since_rst;            // core clocks since the chip left reset (saturates)
    always @(posedge clk) begin
        if (chip_rst) since_rst <= 16'd0;
        else if (since_rst != 16'hFFFF) since_rst <= since_rst + 16'd1;
    end

    wire [3:0] chip_pins_in;         // P3:P0 as lx_chipio drives them
    wire [7:0] pins_o, pins_oe, pins_i;
    wire [7:0] pins_ext = {4'b0000, chip_pins_in};
    generate
        for (gi = 0; gi < 8; gi = gi + 1) begin : g_pad
            assign pins_i[gi] = pins_oe[gi] ? pins_o[gi] : pins_ext[gi];
        end
    endgenerate
    wire [3:0] lamps = pins_i[7:4];  // P7 lane closed, P6 alarm, P5 camera, P4 charged
    wire       chip_rx, chip_tx;

    rvbl2_top #(
        .UART_CLK_FREQ_HZ (CLK_HZ),
        .UART_BAUD_RATE   (BAUD)
    ) u_chip (
        .clk_i   (clk),
        .rst_i   (chip_rst),
        .pins_o  (pins_o),
        .pins_oe (pins_oe),
        .pins_i  (pins_i),
        .tx_o    (chip_tx),
        .rx_i    (chip_rx)
    );

    reg host_tx_q;                   // the laptop sees exactly what the chip sends
    always @(posedge clk) host_tx_q <= chip_tx;
    assign host_tx = host_tx_q;

    // ------------------------------------------------------------------
    // Records from the chip
    // ------------------------------------------------------------------
    wire        crx_valid, rec_valid;
    wire [7:0]  crx_data;
    wire [63:0] rec, window;
    wire [3:0]  nbytes;
    lx_uart_rx #(.CPB(CPB)) u_crx (.clk(clk), .rst(chip_rst), .rxd(chip_tx),
                                   .valid(crx_valid), .data(crx_data));
    lx_records u_rec (.clk(clk), .rst(chip_rst), .rx_valid(crx_valid), .rx_data(crx_data),
                      .rec_valid(rec_valid), .rec(rec), .window(window), .nbytes(nbytes));
    wire [7:0] rec_kind = rec[7:0];

    // ------------------------------------------------------------------
    // Modes: BOOT (lamp test, banner, the chip's ID), LANE, TOUR
    // ------------------------------------------------------------------
    localparam [1:0] M_BOOT = 2'd0, M_LANE = 2'd1, M_TOUR = 2'd2;
    localparam [1:0] B_LAMP = 2'd0, B_BANNER = 2'd1, B_ID = 2'd2;
    reg  [1:0]  mode, bphase;
    reg  [15:0] phase_ms;            // board ms in this mode / boot phase (saturates)
    reg  [5:0]  banner_off;
    reg  [2:0]  boot_idx;            // next boot frame: P C G H K I (0..5); 6 = all sent
    reg         sw9_q, key1_q;
    reg         pend_sight, pend_read, pend_id;
    reg  [3:0]  read_tid;
    reg         fr_start;
    reg  [3:0]  fr_tid;
    wire        fr_idle;
    wire        arrived, quiet, tr_rst_req;
    wire [5:0]  banner_n;
    lx_banner_n u_bn (.n(banner_n));
    reg  id_seen, id_ok;            // the chip's 'I' record has come / matches the build
    wire tour_mode = (mode == M_TOUR);
    wire lane_mode = (mode == M_LANE);
    wire can_issue = fr_idle && !fr_start && !chip_rst && since_rst > BOOT_CYC[15:0];
    // watchdog: after a vehicle leaves, the chip answers with its 'V' record within
    // milliseconds. If 1.5 s pass without one, the board restarts the chip (a warm
    // boot: its boot frames, its identity) instead of waiting for ever.
    reg  [10:0] wd_ms;               // counting down while a decision is awaited (0: none)
    reg         p0_q;
    wire        wd_fire = lane_mode && tick && (wd_ms == 11'd1);

    always @(posedge clk) begin
        fr_start     <= 1'b0;
        chip_rst_req <= 1'b0;
        if (rst) begin
            mode <= M_BOOT; bphase <= B_LAMP; phase_ms <= 16'd0; banner_off <= 6'd0;
            boot_idx <= 3'd0; sw9_q <= 1'b0; key1_q <= 1'b0; wd_ms <= 11'd0; p0_q <= 1'b0;
            pend_sight <= 1'b0; pend_read <= 1'b0; pend_id <= 1'b0; read_tid <= 4'd0; fr_tid <= 4'd0;
        end else begin
            sw9_q  <= swd[9];
            key1_q <= key1;
            p0_q   <= chip_pins_in[0];
            if (tick && phase_ms != 16'hFFFF) phase_ms <= phase_ms + 16'd1;
            if (!lane_mode || (rec_valid && rec_kind == 8'h56)) wd_ms <= 11'd0;     // answered
            else if (p0_q && !chip_pins_in[0]) wd_ms <= 11'd1500;                     // a vehicle left
            else if (tick && wd_ms != 11'd0) wd_ms <= wd_ms - 11'd1;
            if (swd[9] && !sw9_q && !tour_mode) begin            // SW9 up: the tour, from reset
                mode <= M_TOUR; phase_ms <= 16'd0; chip_rst_req <= 1'b1;
                pend_sight <= 1'b0; pend_read <= 1'b0; pend_id <= 1'b0;
            end else if ((!swd[9] && sw9_q && tour_mode) || wd_fire) begin   // SW9 down, or no answer: a warm boot
                mode <= M_BOOT; bphase <= B_ID; phase_ms <= 16'd0; boot_idx <= 3'd0; chip_rst_req <= 1'b1;
                pend_sight <= 1'b0; pend_read <= 1'b0; pend_id <= 1'b0;
            end else if (tour_mode) begin
                if (tr_rst_req) chip_rst_req <= 1'b1;
            end else begin
                // boot display: lamp test (1 s), banner, then the chip's ID
                if (mode == M_BOOT) begin
                    if (bphase == B_LAMP && phase_ms == LAMP_MS) begin
                        bphase <= B_BANNER; phase_ms <= 16'd0;
                    end else if (bphase == B_BANNER && phase_ms == SCROLL_MS) begin
                        phase_ms <= 16'd0;
                        if (banner_off == banner_n - 6'd1) bphase <= B_ID;
                        else banner_off <= banner_off + 6'd1;
                    end else if (bphase == B_ID && phase_ms >= ID_MS && boot_idx == 3'd6 &&
                                 (id_seen || phase_ms >= 16'd5000)) begin
                        mode <= M_LANE; phase_ms <= 16'd0;
                    end
                end
                // frames to build, one at a time: boot first, then the tag
                // reader (CLOnE: its sighting, then its read), then identify
                if (can_issue) begin
                    if (boot_idx != 3'd6) begin
                        fr_tid <= {1'b0, boot_idx}; fr_start <= 1'b1; boot_idx <= boot_idx + 3'd1;
                    end else if (pend_sight) begin
                        fr_tid <= TID_SIGHTING; fr_start <= 1'b1; pend_sight <= 1'b0;
                    end else if (pend_read) begin
                        fr_tid <= read_tid; fr_start <= 1'b1; pend_read <= 1'b0;
                    end else if (pend_id) begin
                        fr_tid <= TID_IDENTIFY; fr_start <= 1'b1; pend_id <= 1'b0;
                    end
                end
                if (lane_mode && arrived && preset != 3'd0) begin  // a vehicle entered: its tag is read
                    pend_read <= 1'b1; read_tid <= {1'b1, preset};
                    if (preset == PRESET_CLONE) pend_sight <= 1'b1;
                end
                if (lane_mode && key1 && !key1_q && !manual) pend_id <= 1'b1;   // KEY1: identify
            end
        end
    end
    wire lamp_test = (mode == M_BOOT) && (bphase == B_LAMP);
    wire in_banner = (mode == M_BOOT) && (bphase == B_BANNER);

    // ------------------------------------------------------------------
    // The lane: one ultrasonic sensor above the lane, looking down. An
    // HC-SR04 is noisy - it jitters a few mm, now and then misses the floor's
    // echo and hears a farther one (a footing, the table's edge), hears a post,
    // or misses altogether - so nothing here trusts a single reading:
    //  1. each reading is the median of the last three: a lone stray never counts;
    //  2. the floor is learnt by agreement - 8 filtered readings within
    //     +/- FLOOR_TOL (0.5 s). Whenever 16 readings (1 s) agree on a FARTHER
    //     distance it is re-learnt: a floor learnt with a toy underneath heals
    //     itself. A floor learnt too FAR is the dangerous one (the empty lane
    //     would stand above it: a phantom vehicle), so the lane is ARMED only
    //     after 4 filtered readings of the floor itself; until then no vehicle
    //     can arrive, and 16 readings agreeing on a NEARER distance are the
    //     floor. Every re-learnt floor disarms the lane. Armed, it is never
    //     re-learnt nearer on its own (that could swallow a parked toy), except
    //     by rule 4;
    //  3. an armed lane: a vehicle arrives when 4 filtered readings in a row (0.25 s)
    //     stand PRESENT_MM above the floor - even three stray echoes in a row cannot -
    //     and leaves after 8 readings of the floor itself (0.5 s). A reading farther
    //     than the floor is a lost echo: it neither counts nor breaks either run. In
    //     between, nothing changes, so nothing near the threshold can make it chatter. Its height (shown,
    //     and a lorry - class 3 - at TALL_MM, the way overhead gantry profilers
    //     classify) is the lowest of the last three filtered heights: a stray echo
    //     can never make a car a lorry. A toy pushed through at a hand's pace is
    //     under it for 15+ readings;
    //  4. a 'vehicle' never taller than LOW_MM that stays 30 s is the floor:
    //     re-learnt (the last guard against a wrong floor).
    // In manual mode (SW8) KEY1 is the vehicle instead.
    // ------------------------------------------------------------------
    localparam integer CLEAR_MM = 8, FLOOR_TOL = 6, LOW_MM = 25;
    wire        s_valid, s_ok;
    wire [11:0] s_mm;
    lx_sonar #(.CLK_HZ(CLK_HZ), .PERIOD(SONAR_PERIOD)) u_sonar (
        .clk(clk), .rst(rst), .echo(echo_s), .trig(sonar_trig), .valid(s_valid), .ok(s_ok), .mm(s_mm));
    reg  [11:0] r1, r2, f_mm;        // the two readings before this one; the filtered reading
    reg  [1:0]  n_r;                 // how many readings the median has (it needs 2 before the third)
    reg         f_valid;             // one cycle: f_mm is new
    reg  [11:0] cand;                // a run of agreeing readings: its running mean ...
    reg  [4:0]  cand_n;              // ... and its length (16+ is a settled distance)
    reg  [11:0] floor_mm, max_mm;
    reg         have_floor, occupied;
    reg         armed;               // the floor itself has been seen since it was learnt
    reg  [2:0]  n_arm;               // consecutive filtered readings of the floor (4: armed)
    reg  [14:0] low_ms;              // how long a low, still 'vehicle' has stood there
    reg  [2:0]  n_occ;               // consecutive filtered readings above PRESENT_MM (4: it has arrived)
    reg  [3:0]  n_clear;             // ... and below CLEAR_MM (8 = it has left: longer than any burst of strays)
    reg  [11:0] hf1, hf2;            // the two filtered heights before this one
    reg  [4:0]  n_bad;               // consecutive no-readings (16 = 1 s: the sensor is gone)
    reg         present, tall;
    reg  [7:0]  clear_ms;
    wire [11:0] lo2  = (r1 < s_mm) ? r1 : s_mm;
    wire [11:0] hi2  = (r1 < s_mm) ? s_mm : r1;
    wire [11:0] med3 = (r2 < lo2) ? lo2 : ((r2 > hi2) ? hi2 : r2);
    wire        agree = (f_mm <= cand + FLOOR_TOL) && (f_mm + FLOOR_TOL >= cand);
    wire        farther = (cand >= floor_mm + 12'd4);
    wire        nearer  = (cand + 12'd4 <= floor_mm);
    wire        beyond  = (f_mm > floor_mm + FLOOR_TOL + 12'd2);          // a lost echo
    wire        at_floor = (f_mm + CLEAR_MM > floor_mm) && !beyond;
    // P2:P1 = SW2:1 if set (01 van, 10 lorry, 11 motorcycle), else the height
    wire [1:0] code = (swd[2:1] != 2'b00) ? swd[2:1] : (tall ? 2'b10 : 2'b00);
    wire       seen = (chip_pins_in[2:0] == {code, 1'b1});   // the chip has seen this vehicle and its class
    always @(posedge clk) begin
        f_valid <= 1'b0;
        if (rst) begin
            r1 <= 12'd0; r2 <= 12'd0; n_r <= 2'd0; f_mm <= 12'd0; n_bad <= 5'd0;
            cand <= 12'd0; cand_n <= 5'd0; floor_mm <= 12'd0; have_floor <= 1'b0; low_ms <= 15'd0;
            armed <= 1'b0; n_arm <= 3'd0;
        end else begin
            if (s_valid && !s_ok) begin                    // no reading: one miss changes nothing
                if (n_bad != 5'd31) n_bad <= n_bad + 5'd1;
                if (n_bad == 5'd15) begin n_r <= 2'd0; cand_n <= 5'd0; end   // 1 s of none: start afresh
            end
            if (s_valid && s_ok) begin                     // 1. the median of three
                n_bad <= 5'd0;
                r2 <= r1; r1 <= s_mm;
                if (n_r == 2'd2) begin f_mm <= med3; f_valid <= 1'b1; end
                else n_r <= n_r + 2'd1;
            end
            if (f_valid) begin                             // 2. runs of agreeing readings
                if (cand_n != 5'd0 && agree) begin
                    if (cand_n != 5'd31) cand_n <= cand_n + 5'd1;
                    cand <= (f_mm >= cand) ? cand + ((f_mm - cand + 12'd2) >> 2)
                                           : cand - ((cand - f_mm + 12'd2) >> 2);
                end else begin
                    cand <= f_mm; cand_n <= 5'd1;
                end
            end
            if (f_valid && have_floor) begin               // the floor itself, 4 in a row: armed
                if (at_floor) begin
                    if (n_arm != 3'd4) n_arm <= n_arm + 3'd1;
                    if (n_arm >= 3'd3) armed <= 1'b1;
                end else n_arm <= 3'd0;
            end
            // every floor below is a new one: the lane is disarmed until it sees it (these come
            // after the arming above, so they win)
            if (!have_floor && cand_n >= 5'd8) begin       // the first floor: 8 readings agree
                floor_mm <= cand; have_floor <= 1'b1; armed <= 1'b0; n_arm <= 3'd0;
            end else if (have_floor && cand_n >= 5'd16 && farther) begin
                floor_mm <= cand; armed <= 1'b0; n_arm <= 3'd0;   // 16 agree on a farther floor
            end else if (have_floor && !armed && !present && cand_n >= 5'd16 && nearer) begin
                floor_mm <= cand; n_arm <= 3'd0;           // never seen since learnt: it was too far
            end
            // 4. a 'vehicle' never taller than LOW_MM, there for 30 s, is the floor itself: once
            //    the latest readings agree (a stray burst only delays it), they are the floor
            if (have_floor && present && max_mm < LOW_MM) begin
                if (tick && low_ms != 15'd32767) low_ms <= low_ms + 15'd1;
                if (low_ms >= 15'd30000 && cand_n >= 5'd8 && cand < floor_mm) begin
                    floor_mm <= cand; low_ms <= 15'd0; armed <= 1'b0; n_arm <= 3'd0;
                end
            end else low_ms <= 15'd0;
        end
    end
    wire [11:0] h_f = (have_floor && f_mm < floor_mm) ? floor_mm - f_mm : 12'd0;
    wire [11:0] h_lo = (hf1 < hf2) ? hf1 : hf2;
    wire [11:0] h_min3 = (h_f < h_lo) ? h_f : h_lo;   // the lowest of the last three filtered heights
    always @(posedge clk) begin                            // 3. arrivals and departures
        if (rst || !lane_mode) begin
            present <= 1'b0; tall <= 1'b0; clear_ms <= 8'd0; occupied <= 1'b0;
            max_mm <= 12'd0; n_occ <= 3'd0; n_clear <= 4'd0; hf1 <= 12'd0; hf2 <= 12'd0;
        end else if (manual) begin
            occupied <= 1'b0; n_occ <= 3'd0; n_clear <= 4'd0; tall <= 1'b0;
            if (key1) begin
                present <= 1'b1; clear_ms <= 8'd0;
            end else if (present && tick) begin
                if (clear_ms >= 8'd30) begin
                    if (seen) present <= 1'b0;
                end else clear_ms <= clear_ms + 8'd1;
            end
        end else begin
            if (s_valid && !s_ok && n_bad == 5'd15) occupied <= 1'b0;
            if (f_valid) begin
                occupied <= (armed || present) && (h_min3 >= PRESENT_MM);   // LEDR0: three readings, a real floor
                hf2 <= hf1; hf1 <= h_f;
                if (h_f >= PRESENT_MM) begin
                    n_clear <= 4'd0;
                    if (n_occ != 3'd4) n_occ <= n_occ + 3'd1;
                    if (n_occ >= 3'd3 && armed) present <= 1'b1; // four readings in a row: a vehicle
                    if (h_min3 > max_mm) max_mm <= h_min3;
                    if (h_min3 >= TALL_MM) tall <= 1'b1;         // latched while it is there
                end else if (!beyond) begin                     // (a lost echo changes nothing)
                    n_occ <= 3'd0;
                    if (h_f < CLEAR_MM) begin                       // the floor itself
                        if (n_clear != 4'd8) n_clear <= n_clear + 4'd1;
                    end else n_clear <= 4'd0;                     // between the thresholds: neither
                end
            end
            // eight clear readings in a row (or the sensor gone), and the chip has seen it: it has left
            if (present && (n_clear == 4'd8 || n_bad >= 5'd16) && seen) begin present <= 1'b0; n_clear <= 4'd0; end
            if (!present && n_occ == 3'd0) begin tall <= 1'b0; max_mm <= 12'd0; end
        end
    end
    wire [3:0] lane_pins = {swd[0], present ? code : 2'b00, present};

    // ------------------------------------------------------------------
    // Sources of frames, and the one channel into the chip
    // ------------------------------------------------------------------
    wire       fr_valid, fr_last, fr_pop;
    wire [7:0] fr_data;
    lx_framer u_framer (.clk(clk), .rst(chip_rst), .start(fr_start), .tid(fr_tid), .now_ms(now_ms),
                        .idle(fr_idle), .valid(fr_valid), .data(fr_data), .last(fr_last), .pop(fr_pop));

    wire       hrx_valid;
    wire [7:0] hrx_data;
    wire       h_valid, h_last, h_pop, h_id_done;
    wire [7:0] h_data;
    lx_uart_rx #(.CPB(CPB)) u_hrx (.clk(clk), .rst(rst), .rxd(host_rx_s), .valid(hrx_valid), .data(hrx_data));
    lx_hostlink #(.TIMEOUT(20 * 10 * CPB)) u_host (
        .clk(clk), .rst(chip_rst), .flush(!lane_mode),
        .rx_valid(hrx_valid), .rx_data(hrx_data),
        .valid(h_valid), .data(h_data), .last(h_last), .pop(h_pop), .id_done(h_id_done));

    wire       tr_valid, tr_last, tr_pop, tr_done, tr_show, tr_checked, tr_pass;
    wire [7:0] tr_data;
    wire [3:0] tr_pins, tr_line, tr_npass, tr_first_fail, tr_lines;
    lx_tour_n u_tn (.n(tr_lines));
    lx_tour #(.BOOT_CYC(BOOT_CYC), .END_CYC(END_CYC)) u_tour (
        .clk(clk), .rst(rst || !tour_mode), .tick(tick), .quiet(quiet),
        .window(window), .nbytes(nbytes), .lamps(lamps),
        .chip_rst_req(tr_rst_req), .pins(tr_pins),
        .valid(tr_valid), .data(tr_data), .last(tr_last), .pop(tr_pop),
        .line(tr_line), .done(tr_done), .npass(tr_npass),
        .first_fail(tr_first_fail), .show(tr_show), .checked(tr_checked), .pass_now(tr_pass));

    // The host's rule after an identify (PROTOCOL.md section 7): the chip measures its
    // ROM in the background for about 2 ms; nothing new goes in until its 'I' record
    // is back (at most ID_WAIT clocks), so its answers come in the order sent.
    localparam [17:0] ID_WAIT = 18'd200000;
    reg  [17:0] idw_cnt;
    reg         id_wait;
    wire        id_sent = (fr_pop && fr_last && fr_tid == TID_IDENTIFY) || h_id_done;
    always @(posedge clk) begin
        if (chip_rst || tour_mode) begin
            id_wait <= 1'b0; idw_cnt <= 18'd0;
        end else if (id_sent) begin
            id_wait <= 1'b1; idw_cnt <= 18'd0;
        end else if (id_wait) begin
            if ((rec_valid && rec_kind == 8'h49) || idw_cnt == ID_WAIT) id_wait <= 1'b0;
            else idw_cnt <= idw_cnt + 18'd1;
        end
    end
    wire [3:0] pins_req = tour_mode ? tr_pins : id_wait ? chip_pins_in : (lane_mode ? lane_pins : 4'b0000);
    lx_chipio #(.CPB(CPB), .SETTLE(SETTLE)) u_io (
        .clk(clk), .rst(chip_rst), .pins_req(pins_req),
        .src_valid({h_valid & lane_mode & !id_wait, fr_valid & !tour_mode & !id_wait, tr_valid & tour_mode}),
        .src_data({h_data, fr_data, tr_data}),
        .src_last({h_last, fr_last, tr_last}),
        .src_pop({h_pop, fr_pop, tr_pop}),
        .txd(chip_rx), .pins(chip_pins_in), .arrived(arrived), .quiet(quiet));

    // ------------------------------------------------------------------
    // What the records say
    // ------------------------------------------------------------------
    wire [15:0] rom_words, rom_crc;
    lx_build_id u_id (.rom_words(rom_words), .rom_crc(rom_crc));
    reg  [2:0]  dec_status;
    reg  [15:0] dec_fare;
    reg  [12:0] dec_ms;              // a decision shows for 4 s: its word 1.5 s, then the fare (0: not showing)
    reg  [3:0]  err_reason;
    reg  [11:0] err_ms, id_ms;
    reg  [15:0] id_crc;
    reg  [7:0]  v_seq;
    reg         v_open, signed_ok;
    reg  [12:0] fresh_ms;            // the outside lamps follow a decision for 4 s
    reg  [7:0]  flash_ms;            // the white camera flash
    reg  [9:0]  beep_ms;
    reg  [1:0]  beep_kind;           // 1 a chirp (charged), 2 three beeps (alarm)
    reg  [6:0]  link_ms;             // LEDR3: the laptop is talking
    reg  [2:0]  pat_wait;            // ms after a 'V' before its lamp pins are read
    // tour mode shows each line's result as latched at its check, never the live
    // pins (the chip restarts at every line: live lamps would blink in between)
    reg  [3:0]  t_lamps;
    reg  [2:0]  t_status;
    reg         t_isv, t_isid, t_pass;
    always @(posedge clk) begin
        if (rst || !tour_mode) begin
            t_lamps <= 4'd0; t_status <= 3'd0; t_isv <= 1'b0; t_isid <= 1'b0; t_pass <= 1'b0;
        end else if (tr_checked) begin
            t_lamps <= lamps; t_status <= dec_status; t_isv <= (dec_ms != 0);
            t_isid <= (dec_ms == 0) && (id_ms != 0); t_pass <= tr_pass;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            dec_status <= 3'd0; dec_fare <= 16'd0; dec_ms <= 13'd0; err_reason <= 4'd0; err_ms <= 12'd0;
            id_ms <= 12'd0; id_crc <= 16'd0; id_seen <= 1'b0; id_ok <= 1'b0;
            v_seq <= 8'd0; v_open <= 1'b0; signed_ok <= 1'b0;
            fresh_ms <= 13'd0; flash_ms <= 8'd0; beep_ms <= 10'd0; beep_kind <= 2'd0;
            link_ms <= 7'd0; pat_wait <= 3'd0;
        end else begin
            if (tick) begin
                if (dec_ms != 0)   dec_ms   <= dec_ms - 13'd1;
                if (err_ms != 0)   err_ms   <= err_ms - 12'd1;
                if (id_ms != 0)    id_ms    <= id_ms - 12'd1;
                if (fresh_ms != 0) fresh_ms <= fresh_ms - 13'd1;
                if (flash_ms != 0) flash_ms <= flash_ms - 8'd1;
                if (beep_ms != 0)  beep_ms  <= beep_ms - 10'd1;
                if (link_ms != 0)  link_ms  <= link_ms - 7'd1;
                if (pat_wait != 0) begin
                    pat_wait <= pat_wait - 3'd1;
                    if (pat_wait == 3'd1) begin                   // the chip has set its lamps
                        if (lamps[1]) flash_ms <= 8'd200;         // P5 camera
                        if (lamps[2])      begin beep_kind <= 2'd2; beep_ms <= 10'd750; end   // P6 alarm
                        else if (lamps[0]) begin beep_kind <= 2'd1; beep_ms <= 10'd80;  end   // P4 charged
                    end
                end
            end
            if (hrx_valid) link_ms <= 7'd80;
            if (chip_rst) begin                                   // a new run: nothing to show yet
                dec_ms <= 13'd0; err_ms <= 12'd0; id_ms <= 12'd0; v_open <= 1'b0; signed_ok <= 1'b0;
                fresh_ms <= 13'd0; flash_ms <= 8'd0; pat_wait <= 3'd0;
                if (!tour_mode) begin id_seen <= 1'b0; id_ok <= 1'b0; end
            end else if (rec_valid) begin
                case (rec_kind)
                    8'h56: begin                                  // 'V': a vehicle's decision
                        dec_status <= rec[18:16]; dec_fare <= rec[47:32]; dec_ms <= DEC_MS;
                        err_ms <= 12'd0; id_ms <= 12'd0;
                        v_seq <= rec[15:8]; v_open <= 1'b1; signed_ok <= 1'b0;
                        fresh_ms <= DEC_MS; pat_wait <= 3'd3;
                    end
                    8'h41: begin                                  // 'A': its authenticator
                        if (v_open && rec[15:8] == v_seq) signed_ok <= 1'b1;
                        v_open <= 1'b0;
                    end
                    8'h45: begin                                  // 'E': a line error
                        err_reason <= rec[11:8]; err_ms <= 12'd2000; dec_ms <= 13'd0;
                    end
                    8'h49: begin                                  // 'I': the chip measured its ROM
                        id_crc <= rec[47:32]; id_ms <= 12'd2000; dec_ms <= 13'd0; v_open <= 1'b0;
                        if (!tour_mode) begin
                            id_seen <= 1'b1;
                            id_ok   <= (rec[15:8] == 8'd4) && (rec[31:16] == rom_words) && (rec[47:32] == rom_crc);
                        end
                    end
                    default: ;
                endcase
            end
        end
    end

    // ------------------------------------------------------------------
    // Display: one thing at a time, by priority
    // ------------------------------------------------------------------
    reg  [4:0]  msg;
    wire [29:0] t_word, t_preset, t_banner;
    lx_text   u_text   (.a(msg), .q(t_word));
    lx_text   u_text_p (.a({2'b01, preset}), .q(t_preset));
    lx_banner u_banner (.a(banner_off), .q(t_banner));

    wire [19:0] h_bcd = bcd5({4'd0, max_mm});
    reg [2:0] dash_pos;              // manual mode: a dash runs across while KEY1 is the vehicle
    reg [6:0] dash_ms;
    always @(posedge clk) begin
        if (rst) begin dash_pos <= 3'd0; dash_ms <= 7'd0; end
        else if (tick) begin
            if (dash_ms == 7'd99) begin
                dash_ms <= 7'd0; dash_pos <= (dash_pos == 3'd5) ? 3'd0 : dash_pos + 3'd1;
            end else dash_ms <= dash_ms + 7'd1;
        end
    end

    wire [19:0] fare_bcd = bcd5(dec_fare);
    function [19:0] bcd5(input [15:0] v);   // binary to 5 BCD digits (double dabble)
        integer i;
        reg [35:0] s;
        begin
            s = {20'd0, v};
            for (i = 0; i < 16; i = i + 1) begin
                if (s[19:16] > 4) s[19:16] = s[19:16] + 4'd3;
                if (s[23:20] > 4) s[23:20] = s[23:20] + 4'd3;
                if (s[27:24] > 4) s[27:24] = s[27:24] + 4'd3;
                if (s[31:28] > 4) s[31:28] = s[31:28] + 4'd3;
                if (s[35:32] > 4) s[35:32] = s[35:32] + 4'd3;
                s = s << 1;
            end
            bcd5 = s[35:16];
        end
    endfunction
    function [9:0] two_digits(input [3:0] n);   // 0..15 -> two decimal char codes
        two_digits = (n >= 4'd10) ? {5'd1, 1'b0, n - 4'd10} : {5'd0, 1'b0, n};
    endfunction
    wire [9:0]  line_dd = two_digits(tr_line + 4'd1);
    wire [9:0]  pass_dd = two_digits(tr_npass);
    wire [9:0]  fail_dd = two_digits(tr_first_fail);
    wire [19:0] id_hex  = {1'b0, id_crc[15:12], 1'b0, id_crc[11:8], 1'b0, id_crc[7:4], 1'b0, id_crc[3:0]};
    wire [29:0] fare_chars = {SP,
                              (fare_bcd[19:16] != 4'd0) ? {1'b0, fare_bcd[19:16]} : SP,
                              (fare_bcd[19:12] != 8'd0) ? {1'b0, fare_bcd[15:12]} : SP,
                              1'b0, fare_bcd[11:8], 1'b0, fare_bcd[7:4], 1'b0, fare_bcd[3:0]};
    wire alarm_word = (dec_status == 3'd3) || (dec_status == 3'd4);     // StOLEn, CLOnE: blink,
    wire [12:0] dec_elapsed = DEC_MS - dec_ms;                         // lit for the first 256 ms
    wire fare_phase = (dec_fare != 16'd0) && (dec_ms <= FARE_FROM);    // after the word's 1.5 s
    wire tour_pass  = tr_done && (tr_npass == tr_lines);

    reg [29:0] chars;
    reg [5:0]  dp;
    reg        all_on, blank;
    always @(*) begin
        msg = MSG_BLANK; chars = t_word; dp = 6'b000000; all_on = 1'b0; blank = 1'b0;
        if (lamp_test) begin
            all_on = 1'b1;
        end else if (in_banner) begin
            chars = t_banner;
        end else if (tour_mode) begin                              // steady phases, latched results
            if (tr_done) begin
                msg = tour_pass ? MSG_PASS : MSG_FAIL;
                chars = {t_word[29:10], tour_pass ? pass_dd : fail_dd};
            end else if (tr_show && t_isv) begin
                msg = {2'b00, t_status};                           // the line's decision
            end else if (tr_show && t_isid) begin
                msg = MSG_ID; chars = {t_word[29:20], id_hex}; dp = 6'b010000;
            end else if (tr_show) begin
                msg = MSG_BLANK;                                   // (no record: the line fails)
            end else begin
                msg = MSG_TEST; chars = {t_word[29:10], line_dd};  // "tESt01" while it runs
            end
        end else if (mode == M_BOOT) begin                         // the chip's ID: "Id.56dE"
            if (id_seen) begin msg = MSG_ID; chars = {t_word[29:20], id_hex}; dp = 6'b010000; end
            else msg = MSG_NO_ID;
        end else if ((chip_pins_in[0] || wd_ms != 0) && !manual) begin   // the vehicle's height ("h  4.5" cm),
                                                                   // until the chip's decision arrives
            chars = {5'd29, SP, (h_bcd[15:12] != 4'd0) ? {1'b0, h_bcd[15:12]} : SP,
                     (h_bcd[15:8] != 8'd0) ? {1'b0, h_bcd[11:8]} : SP, 1'b0, h_bcd[7:4], 1'b0, h_bcd[3:0]};
            dp = 6'b000010;
        end else if (chip_pins_in[0] || wd_ms != 0) begin          // manual: a dash runs across
            chars = {6{SP}};
            chars[5 * (3'd5 - dash_pos) +: 5] = DASH;
        end else if (err_ms != 0) begin
            msg = MSG_ERR; chars = {t_word[29:5], 1'b0, err_reason};
        end else if (id_ms != 0) begin
            msg = MSG_ID; chars = {t_word[29:20], id_hex}; dp = 6'b010000;
        end else if (dec_ms != 0) begin
            msg = {2'b00, dec_status};
            if (fare_phase) begin chars = fare_chars; dp = 6'b000100; end   // "  7.50" (ringgit)
            else blank = alarm_word && dec_elapsed[8];
        end else if (lamps[3]) begin
            msg = MSG_CLOSED;                                      // P7, from the chip
        end else begin
            chars = t_preset;                                      // the tag the next vehicle carries
        end
    end
    // A warm boot (after the tour, or the watchdog) waits a few ms for the chip's
    // 'I' record: the displays, LEDs and lamps hold what they showed until it comes
    // (at most 1 s, then "no Id"), so nothing blinks in between.
    wire freeze = (mode == M_BOOT) && (bphase == B_ID) && !id_seen && (phase_ms < 16'd1000);
    lx_hex6 u_hex (.clk(clk), .hold(freeze), .chars(chars), .dp(dp), .all_on(all_on), .blank(blank), .hex_n(hex_n));

    // ------------------------------------------------------------------
    // LEDs, the outside lamps, the buzzer
    // ------------------------------------------------------------------
    wire       self_ok    = tour_mode ? (tr_done ? tour_pass : (tr_show && t_pass)) : id_ok;
    wire [3:0] lamps_show = tour_mode ? (tr_show && !tr_done ? t_lamps : 4'd0) : lamps;
    wire [9:0] ledr_c = lamp_test ? 10'h3FF :
                        {self_ok, signed_ok && !tour_mode, lamps_show, link_ms != 0,
                         chip_pins_in[0] && !tour_mode, tall, occupied};
    wire beep_on = (beep_kind == 2'd1) ? (beep_ms != 0) :
                   (beep_kind == 2'd2) ? ((beep_ms > 10'd600) ||
                                          (beep_ms > 10'd350 && beep_ms <= 10'd500) ||
                                          (beep_ms > 10'd100 && beep_ms <= 10'd250)) : 1'b0;
    wire buzz = (lamp_test && phase_ms < 16'd100) || (beep_on && !tour_mode);
    assign buzzer      = (buzz && !swd[7]) ^ swd[6];   // SW7 mutes; SW6 for a low-level-trigger module
    // A passive buzzer (a bare coil, no oscillator) only clicks on a level: it needs the tone.
    // 2.4 kHz, the resonance of a 12 mm buzzer; each beep starts a fresh high half, and the
    // pin rests low, so no current stands in the coil between beeps.
    localparam integer TONE_HALF = CLK_HZ / 4800;
    wire       buzz_on = buzz && !swd[7];
    // not held by rst: the lamp test beeps through a reset, and a held tone would be DC in the coil
    reg [15:0] tone_cnt = 16'd0;
    reg        tone_sq = 1'b1;
    always @(posedge clk) begin
        if (!buzz_on) begin
            tone_cnt <= 16'd0; tone_sq <= 1'b1;
        end else if (tone_cnt == TONE_HALF - 1) begin
            tone_cnt <= 16'd0; tone_sq <= ~tone_sq;
        end else tone_cnt <= tone_cnt + 16'd1;
    end
    assign buzzer_tone = buzz_on && tone_sq;
    wire tour_lit = tour_mode && tr_show && !tr_done;   // tour: each line's lamps, steady
    wire [3:0] lamps_c = {lamp_test | (tour_mode ? tour_lit && t_lamps[3] : lamps[3]),
                          lamp_test | (tour_mode ? tour_lit && t_lamps[2] : lamps[2] && fresh_ms != 0),
                          lamp_test | (tour_mode ? tour_lit && t_lamps[1] : lamps[1] && flash_ms != 0),
                          lamp_test | (tour_mode ? tour_lit && t_lamps[0] : lamps[0] && fresh_ms != 0)};
    reg  [9:0] ledr_q;
    reg  [3:0] lamps_q;
    always @(posedge clk) begin
        if (rst) begin ledr_q <= 10'd0; lamps_q <= 4'd0; end
        else if (!freeze) begin ledr_q <= ledr_c; lamps_q <= lamps_c; end
    end
    assign ledr = ledr_q;
    assign {lamp_closed, lamp_red, lamp_white, lamp_green} = lamps_q;
endmodule

// ============================================================================
// Building blocks
// ============================================================================

// Two flip-flops per bit (asynchronous inputs)
module lx_sync #(parameter integer W = 1, parameter [W-1:0] INIT = {W{1'b0}}) (
    input  wire         clk,
    input  wire [W-1:0] d,
    output wire [W-1:0] q
);
    reg [W-1:0] s1 = INIT, s2 = INIT;
    always @(posedge clk) begin
        s1 <= d;
        s2 <= s1;
    end
    assign q = s2;
endmodule

// The output follows the input once it has been stable for MS board milliseconds
module lx_debounce #(parameter integer MS = 5) (
    input  wire clk, rst, tick, d,
    output reg  q
);
    reg [7:0] n;
    always @(posedge clk) begin
        if (rst) begin
            q <= 1'b0; n <= 8'd0;
        end else if (d == q) begin
            n <= 8'd0;
        end else if (tick) begin
            if (n == MS - 1) begin q <= d; n <= 8'd0; end
            else n <= n + 8'd1;
        end
    end
endmodule

// UART transmitter, 8-N-1
module lx_uart_tx #(parameter integer CPB = 271) (
    input  wire       clk, rst, start,
    input  wire [7:0] data,
    output reg        txd,
    output wire       ready
);
    reg [15:0] cnt;
    reg [3:0]  bitn;
    reg [8:0]  sh;
    reg        busy;
    assign ready = !busy;
    always @(posedge clk) begin
        if (rst) begin
            txd <= 1'b1; busy <= 1'b0; cnt <= 16'd0; bitn <= 4'd0; sh <= 9'h1FF;
        end else if (!busy) begin
            if (start) begin
                busy <= 1'b1; txd <= 1'b0; sh <= {1'b1, data}; cnt <= 16'd0; bitn <= 4'd0;
            end
        end else if (cnt != CPB - 1) begin
            cnt <= cnt + 16'd1;
        end else begin
            cnt <= 16'd0;
            if (bitn == 4'd9) busy <= 1'b0;                      // the stop bit is done
            else begin txd <= sh[0]; sh <= {1'b1, sh[8:1]}; bitn <= bitn + 4'd1; end
        end
    end
endmodule

// UART receiver, 8-N-1 (rxd already synchronised); one-cycle valid per byte
module lx_uart_rx #(parameter integer CPB = 271) (
    input  wire       clk, rst, rxd,
    output reg        valid,
    output reg  [7:0] data
);
    localparam [1:0] IDLE = 2'd0, START = 2'd1, DATA = 2'd2, STOP = 2'd3;
    reg [1:0]  st;
    reg [15:0] cnt;
    reg [2:0]  bitn;
    reg [7:0]  sh;
    always @(posedge clk) begin
        valid <= 1'b0;
        if (rst) begin
            st <= IDLE; cnt <= 16'd0; bitn <= 3'd0; sh <= 8'd0; data <= 8'd0;
        end else case (st)
            IDLE:  if (!rxd) begin st <= START; cnt <= 16'd0; end
            START: if (cnt == CPB / 2) begin st <= rxd ? IDLE : DATA; cnt <= 16'd0; bitn <= 3'd0; end
                   else cnt <= cnt + 16'd1;
            DATA:  if (cnt == CPB - 1) begin
                       cnt <= 16'd0; sh <= {rxd, sh[7:1]};
                       if (bitn == 3'd7) st <= STOP;
                       bitn <= bitn + 3'd1;
                   end else cnt <= cnt + 16'd1;
            default: if (cnt == CPB - 1) begin                // the middle of the stop bit
                       st <= IDLE; cnt <= 16'd0;
                       if (rxd) begin valid <= 1'b1; data <= sh; end   // framing error: dropped
                   end else cnt <= cnt + 16'd1;
        endcase
    end
endmodule

// HC-SR04 ultrasonic ranger: a 12.5 us trigger pulse every PERIOD clocks; the
// echo stays high for the sound's round trip. mm = cycles x 171.5 m/s / CLK_HZ.
// Echo must hold a level for 1 us before it counts (spikes picked up on the long
// wire are ignored); no echo within 10 ms, one longer than 25 ms (over 4 m) or
// shorter than ~118 us (under 2 cm, the HC-SR04's minimum) is not a reading
// (ok = 0): a missing or unplugged sensor (Echo held high by the pull-up, or
// low) never reports anything.
module lx_sonar #(parameter integer CLK_HZ = 31250000, parameter integer PERIOD = CLK_HZ / 16) (
    input  wire        clk, rst, echo,
    output reg         trig,
    output reg         valid,        // one cycle: a measurement finished
    output reg         ok,           // ... and it is a reading
    output reg  [11:0] mm
);
    localparam integer TRIG_CYC = CLK_HZ / 80000;           // 12.5 us
    localparam integer RISE_MAX = CLK_HZ / 100;             // 10 ms
    localparam integer HIGH_MAX = CLK_HZ / 40;              // 25 ms
    localparam integer HIGH_MIN = CLK_HZ / 8500;            // ~118 us = 2 cm
    localparam integer GLITCH   = CLK_HZ / 1000000;         // 1 us
    localparam integer MM_MUL   = (171500 * 1024) / (CLK_HZ / 64);   // mm = cycles x MM_MUL >> 16
    localparam [1:0] S_WAIT = 2'd0, S_TRIG = 2'd1, S_RISE = 2'd2, S_HIGH = 2'd3;
    reg [1:0]  st;
    reg [23:0] per, cnt;
    reg        ef;                                           // Echo, deglitched
    reg [7:0]  gcnt;
    wire [33:0] prod = cnt * MM_MUL;
    always @(posedge clk) begin
        if (rst) begin
            ef <= 1'b0; gcnt <= 8'd0;
        end else if (echo == ef) gcnt <= 8'd0;
        else if (gcnt >= GLITCH - 1) begin ef <= echo; gcnt <= 8'd0; end
        else gcnt <= gcnt + 8'd1;
    end
    always @(posedge clk) begin
        valid <= 1'b0;
        if (rst) begin
            st <= S_WAIT; per <= 24'd0; cnt <= 24'd0; trig <= 1'b0; ok <= 1'b0; mm <= 12'd0;
        end else begin
            per <= (per == PERIOD - 1) ? 24'd0 : per + 24'd1;
            case (st)
                S_WAIT: if (per == 0 && !ef) begin st <= S_TRIG; cnt <= 24'd0; trig <= 1'b1; end
                        else if (per == 0) begin valid <= 1'b1; ok <= 1'b0; end   // Echo stuck high
                S_TRIG: if (cnt == TRIG_CYC) begin trig <= 1'b0; cnt <= 24'd0; st <= S_RISE; end
                        else cnt <= cnt + 24'd1;
                S_RISE: if (ef) begin cnt <= 24'd0; st <= S_HIGH; end
                        else if (cnt == RISE_MAX) begin st <= S_WAIT; valid <= 1'b1; ok <= 1'b0; end
                        else cnt <= cnt + 24'd1;
                default: if (!ef) begin                     // S_HIGH: the echo has come back
                             st <= S_WAIT; valid <= 1'b1;
                             ok <= (cnt >= HIGH_MIN);
                             mm <= (prod[33:16] > 18'd4095) ? 12'd4095 : prod[27:16];
                         end else if (cnt == HIGH_MAX) begin st <= S_WAIT; valid <= 1'b1; ok <= 1'b0; end
                         else cnt <= cnt + 24'd1;
            endcase
        end
    end
endmodule

// CRC-16/CCITT-FALSE, one byte
module lx_crc_byte (
    input  wire [15:0] crc,
    input  wire [7:0]  b,
    output reg  [15:0] q
);
    integer k;
    always @(*) begin
        q = crc ^ {b, 8'h00};
        for (k = 0; k < 8; k = k + 1) q = q[15] ? ((q << 1) ^ 16'h1021) : (q << 1);
    end
endmodule

// The one channel into the chip. Sources (0 tour, 1 framer, 2 laptop; lower
// first) offer whole frames a byte at a time; a pin change waits for the line
// to be idle between frames, then nothing else happens for SETTLE clocks. After
// each frame the line stays idle 2 byte-times (PROTOCOL.md section 7).
module lx_chipio #(parameter integer CPB = 271, parameter integer SETTLE = 40000) (
    input  wire        clk, rst,
    input  wire [3:0]  pins_req,
    input  wire [2:0]  src_valid,
    input  wire [23:0] src_data,
    input  wire [2:0]  src_last,
    output wire [2:0]  src_pop,
    output wire        txd,
    output reg  [3:0]  pins,
    output reg         arrived,      // one cycle: P0 has just been raised
    output wire        quiet         // nothing pending, nothing in flight, settled
);
    localparam [1:0] S_IDLE = 2'd0, S_SEND = 2'd1, S_DRAIN = 2'd2;
    reg  [1:0]  st;
    reg  [1:0]  g;
    reg  [19:0] wait_cnt;
    localparam [19:0] SETTLE_CYC = SETTLE, GAP_CYC = 2 * 10 * CPB;   // < 2^20 each
    wire        ready;
    wire        sel_valid = src_valid[g];
    wire        take = (st == S_SEND) && ready && sel_valid;
    wire [7:0]  sel_data = src_data[8 * g +: 8];
    assign src_pop = take ? (3'b001 << g) : 3'b000;
    lx_uart_tx #(.CPB(CPB)) u_tx (.clk(clk), .rst(rst), .start(take), .data(sel_data), .txd(txd), .ready(ready));
    assign quiet = (st == S_IDLE) && (wait_cnt == 0) && (pins == pins_req) && (src_valid == 3'b000);
    always @(posedge clk) begin
        arrived <= 1'b0;
        if (rst) begin
            st <= S_IDLE; g <= 2'd0; wait_cnt <= 20'd0; pins <= 4'd0;
        end else case (st)
            S_IDLE:
                if (wait_cnt != 0) wait_cnt <= wait_cnt - 20'd1;
                else if (src_valid[0]) begin g <= 2'd0; st <= S_SEND; end
                else if (src_valid[1]) begin g <= 2'd1; st <= S_SEND; end
                else if (src_valid[2]) begin g <= 2'd2; st <= S_SEND; end
                else if (pins != pins_req) begin
                    pins <= pins_req; wait_cnt <= SETTLE_CYC;
                    arrived <= pins_req[0] & ~pins[0];
                end
            S_SEND:
                if (take && src_last[g]) st <= S_DRAIN;
            default:                                             // S_DRAIN: the last byte leaves
                if (ready) begin st <= S_IDLE; wait_cnt <= GAP_CYC; end
        endcase
    end
endmodule

// Builds a frame from a template (lx_templates): literal bytes, the live time
// (now, or now - 30 s, captured as the frame starts) and the CRC-16.
module lx_framer (
    input  wire        clk, rst, start,
    input  wire [3:0]  tid,
    input  wire [31:0] now_ms,
    output wire        idle,
    output wire        valid,
    output reg  [7:0]  data,
    output wire        last,
    input  wire        pop
);
    reg        busy;
    reg  [3:0] t_id;
    reg  [5:0] idx;
    reg [15:0] crc;
    reg [31:0] t;
    wire [9:0] op;
    lx_templates u_t (.a({t_id, idx}), .q(op));
    wire [31:0] tt = op[2] ? t - 32'd30000 : t;
    always @(*) begin
        case (op[9:8])
            2'b00:   data = op[7:0];
            2'b01:   data = tt[8 * op[1:0] +: 8];
            default: data = op[0] ? crc[15:8] : crc[7:0];
        endcase
    end
    wire [15:0] crc_next;
    lx_crc_byte u_crc (.crc(crc), .b(data), .q(crc_next));
    assign idle  = !busy;
    assign valid = busy;
    assign last  = (op[9:8] == 2'b10) && op[0];
    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0; t_id <= 4'd0; idx <= 6'd0; crc <= 16'hFFFF; t <= 32'd0;
        end else if (!busy) begin
            if (start) begin busy <= 1'b1; t_id <= tid; idx <= 6'd0; crc <= 16'hFFFF; t <= now_ms; end
        end else if (pop) begin
            if (idx != 6'd0 && op[9:8] != 2'b10) crc <= crc_next;   // not the SOF, not the CRC
            idx <= idx + 6'd1;
            if (last) busy <= 1'b0;
        end
    end
endmodule

// Frames from the laptop: buffered, and offered to the chip only once whole
// (A5, type, len <= 32, payload, CRC). Bytes outside a frame are ignored; a
// frame that stops half-way for TIMEOUT clocks, or does not fit, is dropped.
// The chip itself checks the CRC (and answers an 'E' record if it is wrong).
module lx_hostlink #(parameter integer TIMEOUT = 54200) (
    input  wire       clk, rst, flush,
    input  wire       rx_valid,
    input  wire [7:0] rx_data,
    output wire       valid,
    output wire [7:0] data,
    output wire       last,
    input  wire       pop,
    output wire       id_done        // one cycle: an identify frame ('I') has just been passed on
);
    reg [7:0]  mem [0:63];
    reg [5:0]  wr, cm, rd;           // write, committed (whole frames), read
    reg [1:0]  ws;                   // 0 hunt for A5, 1 type, 2 len, 3 payload + CRC
    reg [5:0]  need;
    reg [19:0] idle;
    reg [5:0]  rd_idx;
    reg [5:0]  rd_len;
    reg [7:0]  rd_type;
    wire       full = (wr + 6'd1 == rd);
    assign id_done = pop && last && (rd_type == 8'h49);
    assign valid = (rd != cm);
    assign data  = mem[rd];
    assign last  = (rd_idx > 6'd2) && (rd_idx == rd_len + 6'd4);
    always @(posedge clk) begin
        if (rst || flush) begin
            wr <= 6'd0; cm <= 6'd0; rd <= 6'd0; ws <= 2'd0; need <= 6'd0; idle <= 20'd0;
            rd_idx <= 6'd0; rd_len <= 6'd0; rd_type <= 8'd0;
        end else begin
            if (rx_valid) begin
                idle <= 20'd0;
                if (ws == 2'd0) begin
                    if (rx_data == 8'hA5 && !full) begin mem[wr] <= rx_data; wr <= wr + 6'd1; ws <= 2'd1; end
                end else if (full) begin
                    wr <= cm; ws <= 2'd0;                         // no room: drop the frame
                end else begin
                    mem[wr] <= rx_data; wr <= wr + 6'd1;
                    case (ws)
                        2'd1: ws <= 2'd2;
                        2'd2: if (rx_data > 8'd32) begin wr <= cm; ws <= 2'd0; end
                              else begin need <= rx_data[5:0] + 6'd2; ws <= 2'd3; end
                        default: begin
                            need <= need - 6'd1;
                            if (need == 6'd1) begin ws <= 2'd0; cm <= wr + 6'd1; end
                        end
                    endcase
                end
            end else if (ws != 2'd0) begin
                if (idle == TIMEOUT) begin wr <= cm; ws <= 2'd0; idle <= 20'd0; end
                else idle <= idle + 20'd1;
            end
            if (pop) begin
                rd <= rd + 6'd1;
                if (rd_idx == 6'd1) rd_type <= data;
                if (rd_idx == 6'd2) rd_len <= data[5:0];
                rd_idx <= last ? 6'd0 : rd_idx + 6'd1;
            end
        end
    end
endmodule

// Records from the chip: 8 bytes, CRC-16 over bytes 0-5 in bytes 6-7. Counts
// 8-byte groups from reset; if a group fails its CRC, it hunts byte by byte
// until 8 bytes check again. `window` is the last 8 bytes, as top.sv's buffer.
module lx_records (
    input  wire        clk, rst,
    input  wire        rx_valid,
    input  wire [7:0]  rx_data,
    output reg         rec_valid,
    output reg  [63:0] rec,          // byte 0 (the kind) in bits 7:0
    output reg  [63:0] window,       // the last 8 bytes, the newest in bits 63:56
    output reg  [3:0]  nbytes        // bytes since reset, up to 8
);
    reg [2:0]  cnt;
    reg        hunt, chk;
    wire [15:0] c1, c2, c3, c4, c5, c6;
    lx_crc_byte u0 (.crc(16'hFFFF), .b(window[7:0]),   .q(c1));
    lx_crc_byte u1 (.crc(c1),       .b(window[15:8]),  .q(c2));
    lx_crc_byte u2 (.crc(c2),       .b(window[23:16]), .q(c3));
    lx_crc_byte u3 (.crc(c3),       .b(window[31:24]), .q(c4));
    lx_crc_byte u4 (.crc(c4),       .b(window[39:32]), .q(c5));
    lx_crc_byte u5 (.crc(c5),       .b(window[47:40]), .q(c6));
    wire [7:0] k = window[7:0];
    wire good = (c6 == window[63:48]) &&
                (k == 8'h56 || k == 8'h41 || k == 8'h45 || k == 8'h51 || k == 8'h49);
    always @(posedge clk) begin
        rec_valid <= 1'b0;
        if (rst) begin
            cnt <= 3'd0; hunt <= 1'b0; chk <= 1'b0; window <= 64'd0; nbytes <= 4'd0; rec <= 64'd0;
        end else begin
            chk <= 1'b0;
            if (rx_valid) begin
                window <= {rx_data, window[63:8]};
                if (nbytes != 4'd8) nbytes <= nbytes + 4'd1;
                cnt <= cnt + 3'd1;
                chk <= hunt ? (nbytes >= 4'd7) : (cnt == 3'd7);
            end
            if (chk) begin
                if (good) begin rec_valid <= 1'b1; rec <= window; hunt <= 1'b0; cnt <= 3'd0; end
                else if (!hunt) hunt <= 1'b1;
            end
        end
    end
endmodule

// Tour mode: plays lx_tour_rom - each line from a chip reset, then its pins and
// frames in order; at the line's end it compares the last 8 bytes and the lamps
// with the golden answer (lx_tour_exp), as ./emu's -r and -o do. What a person
// sees is paced and steady: "tESt nn" for TEST_MS (the line runs, in a few ms,
// inside it), then the line's result for SHOW_MS (show = 1), then the next line.
module lx_tour #(
    parameter integer BOOT_CYC = 10000,
    parameter integer END_CYC  = 200000,
    parameter integer TEST_MS  = 500,
    parameter integer SHOW_MS  = 900
) (
    input  wire        clk, rst, tick, quiet,
    input  wire [63:0] window,
    input  wire [3:0]  nbytes,
    input  wire [3:0]  lamps,
    output reg         chip_rst_req,
    output reg  [3:0]  pins,
    output wire        valid,
    output wire [7:0]  data,
    output wire        last,
    input  wire        pop,
    output reg  [3:0]  line,
    output reg         done,
    output reg  [3:0]  npass,
    output reg  [3:0]  first_fail,
    output wire        show,         // the line's result is on show
    output reg         checked,      // one cycle: the line was just compared ...
    output wire        pass_now      // ... and this is its verdict
);
    localparam [2:0] T_RESET = 3'd0, T_BOOT = 3'd1, T_RUN = 3'd2, T_PINS = 3'd3, T_END = 3'd4,
                     T_WAIT = 3'd5, T_PACE = 3'd6, T_SHOW = 3'd7;
    reg  [2:0]  st;
    reg  [9:0]  pc;
    reg  [19:0] cnt;
    reg  [15:0] line_ms;
    wire [9:0]  op;
    wire [68:0] exp;
    lx_tour_rom u_rom (.a(pc), .q(op));
    lx_tour_exp u_exp (.a(line), .q(exp));
    assign valid    = (st == T_RUN) && !op[9];
    assign data     = op[7:0];
    assign last     = op[8];
    assign show     = (st == T_SHOW) || done;
    assign pass_now = (nbytes == 4'd8) && (window == exp[63:0]) && (!exp[68] || lamps == exp[67:64]);
    always @(posedge clk) begin
        chip_rst_req <= 1'b0;
        checked      <= 1'b0;
        if (rst) begin
            st <= T_RESET; pc <= 10'd0; cnt <= 20'd0; line <= 4'd0; line_ms <= 16'd0;
            done <= 1'b0; npass <= 4'd0; first_fail <= 4'd0; pins <= 4'd0;
        end else if (!done) begin
            if (tick && line_ms != 16'hFFFF) line_ms <= line_ms + 16'd1;
            case (st)
                T_RESET: begin                                    // every ./emu run starts from reset
                    pins <= 4'd0; chip_rst_req <= 1'b1; cnt <= 20'd0; line_ms <= 16'd0; st <= T_BOOT;
                end
                T_BOOT:                                           // the chip starts
                    if (cnt == BOOT_CYC) st <= T_RUN; else cnt <= cnt + 20'd1;
                T_RUN:
                    if (op[9:8] == 2'b10) begin                   // set the pins, then let them settle
                        pins <= op[3:0]; pc <= pc + 10'd1; cnt <= 20'd0; st <= T_PINS;
                    end else if (op[9:8] == 2'b11) begin          // end of the line
                        cnt <= 20'd0; st <= T_END;
                    end else if (pop) pc <= pc + 10'd1;           // a byte went out
                T_PINS:
                    if (cnt != 20'd8) cnt <= cnt + 20'd1;
                    else if (quiet) st <= T_RUN;
                T_END:                                            // the last frame out, pins settled
                    if (cnt != 20'd8) cnt <= cnt + 20'd1;
                    else if (quiet) begin cnt <= 20'd0; st <= T_WAIT; end
                T_WAIT:                                           // the chip decides and answers
                    if (cnt == END_CYC) begin
                        checked <= 1'b1;
                        if (pass_now) npass <= npass + 4'd1;
                        else if (first_fail == 4'd0) first_fail <= line + 4'd1;
                        st <= T_PACE;
                    end else cnt <= cnt + 20'd1;
                T_PACE:                                           // "tESt nn" for TEST_MS in all
                    if (line_ms >= TEST_MS) begin line_ms <= 16'd0; st <= T_SHOW; end
                default:                                          // T_SHOW: the result, then the next line
                    if (line_ms >= SHOW_MS) begin
                        pc <= pc + 10'd1;
                        if (op_next == 10'h3FF) done <= 1'b1;
                        else begin line <= line + 4'd1; st <= T_RESET; end
                    end
            endcase
        end
    end
    wire [9:0] op_next;
    lx_tour_rom u_rom_n (.a(pc + 10'd1), .q(op_next));
endmodule

// Six 7-segment digits, common anode on the DE10-Lite: a segment is lit by 0
module lx_hex6 (
    input  wire        clk,
    input  wire        hold,         // keep showing the last picture
    input  wire [29:0] chars,        // HEX5 in bits 29:25 ... HEX0 in bits 4:0
    input  wire [5:0]  dp,
    input  wire        all_on, blank,
    output reg  [47:0] hex_n         // HEX5 in bits 47:40 ... HEX0 in bits 7:0
);
    wire [6:0] s0, s1, s2, s3, s4, s5;
    lx_font f0 (.a(chars[4:0]),   .q(s0));
    lx_font f1 (.a(chars[9:5]),   .q(s1));
    lx_font f2 (.a(chars[14:10]), .q(s2));
    lx_font f3 (.a(chars[19:15]), .q(s3));
    lx_font f4 (.a(chars[24:20]), .q(s4));
    lx_font f5 (.a(chars[29:25]), .q(s5));
    wire [47:0] on = {dp[5], s5, dp[4], s4, dp[3], s3, dp[2], s2, dp[1], s1, dp[0], s0};
    always @(posedge clk) if (!hold) hex_n <= all_on ? 48'd0 : blank ? {48{1'b1}} : ~on;
endmodule

`default_nettype wire
